import { AUTH_PAGE_MODULE_TYPES, ModuleType } from '@/types'

const kebabCase = (str: string): string => {
	return (
		str
			// handle camelCase and PascalCase by adding space before capitals
			.replace(/([a-z])([A-Z])/g, '$1 $2')
			.replace(/([A-Z])([A-Z][a-z])/g, '$1 $2')
			// convert all non-alphanumeric characters to spaces
			.replace(/[^a-zA-Z0-9]/g, ' ')
			// convert to lowercase
			.toLowerCase()
			// replace multiple spaces with single space and trim
			.trim()
			.replace(/\s+/g, '-')
	)
}

const kebabPath = <T extends string | null>(
	str: T
): T extends string ? string : string | null =>
	// @ts-expect-error - typescript cannot narrow this properly
	str
		?.split('/')
		.map((part) => kebabCase(part))
		.join('/') ?? null

const path = {
	join: (...args: string[]) =>
		args
			.join('/')
			// remove double slash due to join
			.replaceAll(/\/+/g, '/'),
	basename: (filePath: string) => {
		const parts = filePath.split('/')
		return parts[parts.length - 1]
	},
	extname: (filePath: string) => {
		const parts = filePath.split('.')
		return parts.length > 1 ? `.${parts[parts.length - 1]}` : ''
	},
	dirname: (filePath: string) => {
		const parts = filePath.split('/')
		return parts.slice(0, parts.length - 1).join('/')
	}
}

export const WEB_APP_SRC_ROOT = '/apps/web/src'
export const EXPO_APP_SRC_ROOT = '/apps/mobile/src'
export const BACKEND_APP_SRC_ROOT = `${WEB_APP_SRC_ROOT}/app/api`

const getDefaultFolderForModuleType = ({
	moduleType,
	pathSegment,
	aliasRenderName,
	digitSuffix
}: {
	moduleType: ModuleType
	pathSegment: string | null
	aliasRenderName: string
	digitSuffix: number | null
}) => {
	const forPathSegment = () => {
		return path.join(
			WEB_APP_SRC_ROOT,
			'/app/',
			pathSegment === '/' && !digitSuffix
				? '/'
				: `${kebabPath(pathSegment) ?? kebabCase(aliasRenderName)}${
						digitSuffix ? `-${digitSuffix}` : ''
				  }`
		)
	}
	switch (moduleType) {
		case ModuleType.PAGE:
		case ModuleType.DESIGN_SYSTEM_PAGE:
			return forPathSegment()
		case ModuleType.AUTH_PAGE_SIGN_UP:
		case ModuleType.AUTH_PAGE_SIGN_IN:
		case ModuleType.AUTH_PAGE_LOGOUT: {
			if (pathSegment) {
				return forPathSegment()
			}
			return path.join(
				WEB_APP_SRC_ROOT,
				'/app/account/',
				`${moduleType
					.replace('AUTH_PAGE_', '')
					.replace('_', '')
					.toLowerCase()}${digitSuffix ? `-${digitSuffix}` : ''}`
			)
		}
		case ModuleType.EXPO_PAGE:
			return path.join(
				EXPO_APP_SRC_ROOT,
				'/app/',
				pathSegment === '/' && !digitSuffix
					? ''
					: `${kebabPath(pathSegment) ?? kebabCase(aliasRenderName)}${
							digitSuffix ? `-${digitSuffix}` : ''
					  }`
			)
		case ModuleType.FUNCTION:
			return path.join(
				BACKEND_APP_SRC_ROOT,
				`${
					pathSegment?.startsWith('/api')
						? kebabPath(pathSegment.slice(4))
						: kebabPath(pathSegment) ?? kebabCase(aliasRenderName)
				}${digitSuffix ? `-${digitSuffix}` : ''}`
			)
		case ModuleType.DESIGN_SYSTEM_COMPONENT:
		case ModuleType.COMPONENT:
			return path.join(WEB_APP_SRC_ROOT, '/components/')
		case ModuleType.FILE: {
			throw new Error(
				'Cannot get default file path for file module type as the entire purpose is to map old module types to the new file path'
			)
		}
		default: {
			const exhaustiveCheck: never = moduleType
			return exhaustiveCheck
		}
	}
}

export const getDefaultFilename = ({
	moduleType,
	aliasRenderName,
	digitSuffix
}: {
	moduleType: ModuleType
	aliasRenderName: string
	digitSuffix: number | null
}) => {
	switch (moduleType) {
		case ModuleType.PAGE:
		case ModuleType.DESIGN_SYSTEM_PAGE:
			return 'page.jsx'
		case ModuleType.EXPO_PAGE:
			return 'index.jsx'
		case ModuleType.AUTH_PAGE_LOGOUT:
		case ModuleType.AUTH_PAGE_SIGN_IN:
		case ModuleType.AUTH_PAGE_SIGN_UP:
			return 'page.jsx'
		case ModuleType.DESIGN_SYSTEM_COMPONENT:
		case ModuleType.COMPONENT:
			return `${kebabCase(aliasRenderName)}${digitSuffix ?? ''}.jsx`
		case ModuleType.FUNCTION:
			return 'route.js'
		case ModuleType.FILE: {
			throw new Error(
				'Cannot get default file path for file module type as the entire purpose is to map old module types to the new file path'
			)
		}
		default: {
			const exhaustiveCheck: never = moduleType
			return exhaustiveCheck
		}
	}
}

const getDefaultFilePathForProjectData = ({
	moduleType,
	filePath,
	pathSegment,
	aliasRenderName,
	digitSuffix
}: {
	moduleType: ModuleType
	filePath: string | null
	pathSegment: string | null
	aliasRenderName: string
	digitSuffix: number | null
}) => {
	if (!filePath) {
		return path.join(
			getDefaultFolderForModuleType({
				moduleType,
				pathSegment,
				aliasRenderName,
				digitSuffix
			}),
			getDefaultFilename({ moduleType, aliasRenderName, digitSuffix })
		)
	}
	if (digitSuffix === null) {
		return filePath
	}
	const basename = path.basename(filePath)
	const extname = path.extname(filePath)
	return path.join(
		path.dirname(filePath),
		`${basename}-${digitSuffix}${extname}`
	)
}

export const getModuleTypeFromFilePath = ({
	filePath: filePathArg
}: {
	filePath: string
}) => {
	const filePath = filePathArg.trim().toLowerCase()
	for (const moduleType of AUTH_PAGE_MODULE_TYPES) {
		const moduleTypePath = getDefaultFilePathForProjectData({
			moduleType,
			filePath: null,
			pathSegment: null,
			aliasRenderName: '',
			digitSuffix: null
		})
		if (filePath === moduleTypePath) {
			return moduleType
		}
	}
	// this is the web app
	if (filePath.startsWith(WEB_APP_SRC_ROOT)) {
		// this is the app folder which is used for routing
		if (filePath.startsWith(`${WEB_APP_SRC_ROOT}/app/`)) {
			if (filePath.endsWith('/page.jsx')) {
				return ModuleType.PAGE
			}
		}
		if (filePath.endsWith('.jsx')) {
			return ModuleType.COMPONENT
		}
	}
	if (filePath.startsWith(BACKEND_APP_SRC_ROOT)) {
		if (filePath.endsWith('/route.js')) {
			return ModuleType.FUNCTION
		}
	}
	if (filePath.startsWith(`${EXPO_APP_SRC_ROOT}/app`)) {
		const fileName = path.basename(filePath)
		if (
			fileName?.endsWith('.jsx') &&
			!fileName.endsWith('_layout.jsx') &&
			!fileName.startsWith('+')
		) {
			return ModuleType.EXPO_PAGE
		}
	}
	return ModuleType.FILE
}
